/**
 * AI movies: an idea (or the user's own script) becomes a script, characters and shots,
 * and each shot is generated by a video model. Prices are credits per second of video
 * (1 cr ≈ $0.01), about twice what the model costs us, so every movie stays profitable
 * after refunded blocked shots, failed takes, frames and storage.
 */

export type MovieGenre = "action" | "drama" | "romance" | "comedy" | "thriller";
export type MovieStyle = "cinematic" | "realistic" | "anime";
export type MovieRatio = "9:16" | "16:9";
export type MovieStatus = "draft" | "making" | "done" | "failed";
export type ModelTier = "draft" | "standard" | "action" | "lead" | "cinematic";
export type MovieQuality = "budget" | "balanced" | "premium" | "custom";
export type ShotKind = "wide" | "detail" | "close" | "action";
export type ShotState = "planned" | "queued" | "frame" | "making" | "done" | "blocked" | "failed";

export const GENRES: Record<MovieGenre, { name: string; icon: string }> = {
  action: { name: "Action", icon: "zap" },
  drama: { name: "Drama", icon: "drama" },
  romance: { name: "Romance", icon: "heart" },
  comedy: { name: "Comedy", icon: "laugh" },
  thriller: { name: "Thriller", icon: "eye" },
};
export const STYLES: Record<MovieStyle, string> = { cinematic: "Cinematic", realistic: "Realistic", anime: "Anime" };
export const LENGTHS = [10, 15, 30, 60, 90];
export const TIMES = ["Day", "Night", "Morning", "Evening"];

export interface ModelInfo {
  name: string;
  model: string;
  /** credits per second of video */
  rate: number;
  desc: string;
  /** shot lengths this model can make */
  durations: number[];
}

export const MODELS: Record<ModelTier, ModelInfo> = {
  draft: { name: "Draft", model: "Veo 3.1 Lite", rate: 10, desc: "Quick and cheap. Simple, calm scenes.", durations: [4, 6, 8] },
  standard: { name: "Standard", model: "Wan 3", rate: 20, desc: "Good everyday quality", durations: [4, 5, 6, 7, 8, 10] },
  action: { name: "Action", model: "Kling 3.0 Pro", rate: 35, desc: "Fast motion: fights, chases, stunts", durations: [4, 5, 6, 7, 8, 10] },
  lead: { name: "Lead face", model: "Seedance 2.0", rate: 50, desc: "Keeps a character’s face the same in every shot", durations: [4, 5, 6, 7, 8, 10] },
  cinematic: { name: "Cinematic", model: "Veo 3.1", rate: 80, desc: "Best picture and sound", durations: [4, 6, 8] },
};
export const MODEL_ORDER: ModelTier[] = ["draft", "standard", "action", "lead", "cinematic"];

export const MOVIE_COST = { script: 5, read: 2, portrait: 2, scene: 1, buffer: 0.1 };

export interface ScriptLine { who: string; text: string }
export interface Scene { id: string; place: string; time: string; text: string; lines: ScriptLine[] }

export interface Character {
  id: string;
  name: string;
  role: string;
  /** looks and personality, used in every prompt */
  desc: string;
  /** colour of the placeholder portrait */
  hue: number;
  /** portrait version (each new AI portrait adds one) */
  ver: number;
  /** storage key of the AI portrait */
  portrait?: string | null;
  /** storage key of the user's photo, when the character uses one */
  photo?: string | null;
  /** what the user agreed to when using a photo */
  consent?: { at: string; text: string } | null;
}

export interface Shot {
  id: string;
  scene: string;
  title: string;
  /** what happens, for the video model */
  desc: string;
  sec: number;
  kind: ShotKind;
  cast: string[];
  /** the line spoken in this shot, if any */
  say?: string;
  model: ModelTier;
  state: ShotState;
  /** storage keys */
  frame?: string | null;
  file?: string | null;
  /** model request while it's being made */
  requestId?: string | null;
  error?: string | null;
}

export interface MovieSettings {
  genre: MovieGenre;
  length: number;
  ratio: MovieRatio;
  style: MovieStyle;
  source: "ai" | "own";
  idea: string;
  fromOwn?: boolean;
  /** the script changed since the shots were planned */
  shotsStale?: boolean;
}

export interface Movie {
  id: string;
  userId: string;
  name: string;
  status: MovieStatus;
  settings: MovieSettings;
  script: Scene[];
  cast: Character[];
  shots: Shot[];
  quality: MovieQuality;
  held: number;
  used: number;
  files: { video?: string | null };
  error: string | null;
  createdAt: Date;
  updatedAt: Date;
}

/** What the browser may see: storage keys become "has a file" flags. */
export type PublicMovie = Omit<Movie, "userId" | "files" | "cast" | "shots"> & {
  hasVideo: boolean;
  cast: (Omit<Character, "portrait" | "photo" | "consent"> & { hasPortrait: boolean; hasPhoto: boolean })[];
  shots: (Omit<Shot, "frame" | "file" | "requestId"> & { hasFrame: boolean; hasFile: boolean })[];
};

export function toPublicMovie(m: Movie): PublicMovie {
  const { userId: _u, files, cast, shots, ...rest } = m;
  return {
    ...rest,
    hasVideo: Boolean(files.video),
    cast: cast.map(({ portrait, photo, consent: _c, ...c }) => ({ ...c, hasPortrait: Boolean(portrait), hasPhoto: Boolean(photo) })),
    shots: shots.map(({ frame, file, requestId: _r, ...s }) => ({ ...s, hasFrame: Boolean(frame), hasFile: Boolean(file) })),
  };
}

/** Balanced quality: the right model for each kind of shot. */
export function autoModel(sh: Pick<Shot, "kind" | "cast">, quality: MovieQuality): ModelTier {
  if (quality === "budget") return "draft";
  if (quality === "premium") return "cinematic";
  if (sh.kind === "action") return "action";
  if (sh.kind === "close" && sh.cast.length) return "lead";
  return "standard";
}

/**
 * Lengthen shots (to lengths their model can make) until they fill about the chosen
 * movie length; the script writer often plans a little short.
 */
export function fillLength<T extends Pick<Shot, "sec" | "model">>(shots: T[], target: number): T[] {
  const out = shots.map((s) => ({ ...s }));
  const total = () => out.reduce((a, s) => a + s.sec, 0);
  for (let guard = 0; guard < 50 && total() < target * 0.95; guard++) {
    // grow the shortest shot that can still grow without passing the target
    const grow = out
      .map((s) => ({ s, next: MODELS[s.model].durations.find((d) => d > s.sec) }))
      .filter((x) => x.next && total() - x.s.sec + x.next <= target * 1.05)
      .sort((a, b) => a.s.sec - b.s.sec)[0];
    if (!grow) break;
    grow.s.sec = grow.next!;
  }
  return out;
}

/** The nearest length the model can make. */
export function fitDuration(sec: number, tier: ModelTier) {
  return MODELS[tier].durations.reduce((best, d) => (Math.abs(d - sec) < Math.abs(best - sec) ? d : best));
}

export const shotCost = (sh: Pick<Shot, "sec" | "model">) => sh.sec * MODELS[sh.model].rate;

/** Price of making the movie: per model, plus a 10% retry buffer that's returned if unused. */
export function estimateMovie(shots: Pick<Shot, "sec" | "model">[]) {
  const by = new Map<ModelTier, { sec: number; n: number }>();
  for (const sh of shots) {
    const b = by.get(sh.model) ?? { sec: 0, n: 0 };
    b.sec += sh.sec;
    b.n++;
    by.set(sh.model, b);
  }
  const lines = MODEL_ORDER.filter((k) => by.get(k)).map((k) => {
    const b = by.get(k)!, m = MODELS[k];
    return { label: `${m.model} · ${b.n} shot${b.n > 1 ? "s" : ""}`, detail: `${b.sec.toLocaleString("en-US")} s × ${m.rate} cr`, credits: b.sec * m.rate };
  });
  const sub = lines.reduce((a, l) => a + l.credits, 0);
  const buffer = Math.ceil(sub * MOVIE_COST.buffer);
  return { lines, sub, buffer, total: sub + buffer };
}

/* ── script length ── */
const words = (t: string) => (t || "").trim().split(/\s+/).filter(Boolean).length;
/** About how long a scene plays: some time for the action, plus the lines being spoken. */
export const sceneSec = (sc: Pick<Scene, "text" | "lines">) => Math.round(3 + words(sc.text) * 0.3 + sc.lines.reduce((a, l) => a + 1 + words(l.text) * 0.42, 0));
export const scriptSec = (script: Scene[]) => script.reduce((a, sc) => a + sceneSec(sc), 0);

/** Words that are never made into a movie (checked before the AI moderation too). */
export const BLOCKED_WORDS = /\b(sex|sexual|nude|naked|porn|nsfw|erotic)\b/i;

/** Text shown for a photo character, stored with the movie. */
export const PHOTO_CONSENT = "This is me, or the person in the photo agreed to be in this movie. They’re an adult and not a famous person.";

/* ── keeping browser edits safe ── */
const clip = (s: unknown, n: number) => String(s ?? "").slice(0, n);
export function sanitizeScript(raw: unknown): Scene[] {
  if (!Array.isArray(raw)) return [];
  return raw.slice(0, 30).map((sc, i) => ({
    id: /^[\w-]{1,40}$/.test(String(sc?.id)) ? String(sc.id) : `s${i + 1}`,
    place: clip(sc?.place, 80) || "Somewhere",
    time: TIMES.includes(sc?.time) ? sc.time : "Day",
    text: clip(sc?.text, 1200),
    lines: Array.isArray(sc?.lines) ? sc.lines.slice(0, 20).map((l: { who?: unknown; text?: unknown }) => ({ who: clip(l?.who, 40) || "Narrator", text: clip(l?.text, 300) })) : [],
  }));
}
